-- Catalog and privilege metadata only. Does not call either feature RPC or read player rows.
SELECT jsonb_build_object(
 'namespace',(SELECT jsonb_build_object('name',n.nspname,'owner',pg_get_userbyid(n.nspowner),'acl',n.nspacl) FROM pg_namespace n WHERE n.nspname='item_use_internal'),
 'receipt_table',(SELECT jsonb_build_object('owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl) FROM pg_class c WHERE c.oid=to_regclass('item_use_internal.moonberry_receipts')),
 'receipt_columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=to_regclass('item_use_internal.moonberry_receipts') AND a.attnum>0 AND NOT a.attisdropped),
 'receipt_constraints',(SELECT jsonb_agg(jsonb_build_object('name',conname,'type',contype,'definition',pg_get_constraintdef(oid,true),'validated',convalidated) ORDER BY conname) FROM pg_constraint WHERE conrelid=to_regclass('item_use_internal.moonberry_receipts')),
 'receipt_policies',(SELECT count(*) FROM pg_policy WHERE polrelid=to_regclass('item_use_internal.moonberry_receipts')),
 'functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'language',(SELECT lanname FROM pg_language WHERE oid=p.prolang),'volatility',p.provolatile,'return_type',(SELECT jsonb_build_object('schema',n.nspname,'name',t.typname,'setof',p.proretset) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE t.oid=p.prorettype),'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl,'body_md5',md5(p.prosrc),'definition',pg_get_functiondef(p.oid)) ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('share_moonberry','read_moonberry_share_moments','validate_moonberry_depleted_stack')),
 'quantity_constraint',(SELECT jsonb_build_object('definition',pg_get_constraintdef(oid,true),'validated',convalidated) FROM pg_constraint WHERE conrelid='public.user_items'::regclass AND conname='user_items_quantity_check'),
 'depletion_trigger',(SELECT jsonb_build_object('name',tgname,'type',tgtype,'enabled',tgenabled,'internal',tgisinternal,'when_is_null',tgqual IS NULL,'argument_count',tgnargs,'function',tgfoid::regprocedure::text,'columns',tgattr::smallint[],'definition',pg_get_triggerdef(oid,true)) FROM pg_trigger WHERE tgrelid='public.user_items'::regclass AND tgname='user_items_validate_depleted_stack'),
 'rpc_acl',(SELECT jsonb_agg(jsonb_build_object('function',p.proname,'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY p.proname,x.grantee,x.privilege_type) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x WHERE n.nspname='public' AND p.proname IN ('share_moonberry','read_moonberry_share_moments')),
 'private_acl',(SELECT jsonb_agg(to_jsonb(q) ORDER BY q.object,q.grantee,q.privilege) FROM (
   SELECT 'schema'::text AS object,CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END AS grantee,x.privilege_type AS privilege,x.is_grantable AS grantable FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x WHERE n.nspname='item_use_internal'
   UNION ALL SELECT 'table',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type,x.is_grantable FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x WHERE c.oid=to_regclass('item_use_internal.moonberry_receipts')) q),
 'role_checks',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'public_usage',has_schema_privilege(r.oid,'public','USAGE'),'private_usage',has_schema_privilege(r.oid,'item_use_internal','USAGE'),'private_create',has_schema_privilege(r.oid,'item_use_internal','CREATE'),'receipt_any',has_table_privilege(r.oid,'item_use_internal.moonberry_receipts','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN'),'share_execute',has_function_privilege(r.oid,'public.share_moonberry(uuid,uuid,uuid)','EXECUTE'),'history_execute',has_function_privilege(r.oid,'public.read_moonberry_share_moments(uuid)','EXECUTE')) ORDER BY r.rolname) FROM pg_roles r WHERE r.rolname IN ('anon','authenticated','service_role'))
) AS feature_postflight;
